INSERT INTO poems (id, title, author, content, dynasty, original_id, created_time, author_simple) VALUES
  (11040, '次韻董令升四詠 性樂堂', '朱翌', '且置紛紛事百端，從公繫馬白雲邊。
欲知太守樂其樂，山色溪聲得兩全。', '1140', '6757a605-c242-4118-a963-0485f011c49e', '2025-10-21 16:54:22', '朱翌'),
  (22080, '肅宗', '王十朋', '張后宮中巧弄權，上皇西內老誰憐。
杜陵獨念君臣義，長向雲安拜杜鵑。', '1170', '3b97f105-db50-4ad2-9da1-886b4f922cc3', '2025-10-21 21:10:57', '王十朋'),
  (33120, '頭陀寺觀王簡栖碑有感偶餘眉州酒樽獨酌遂醉', '陸游', '舟車如織喜身閑，獨訪遺碑草棘間。
世遠空驚閲陵谷，文浮未可敵江山。
老僧西逝新成塔，舊守東歸正掩關。
笑我驅馳竟安往，夕陽飛鳥亦知還。', '1186', '89594647-321b-4965-8c7a-71622d797dcb', '2025-10-22 01:32:25', '陆游'),
  (44160, '罷丞零陵忽病傷寒謁醫兩旬如負擔者日遠日重改謁唐醫公亮九日而無病矣謝以長句', '楊萬里', '料病如料敵，用藥如中的。
淮陰百戰有百勝，由基百發無一失。
老唐脈法明更高，閲人二豎可得逃。
探囊起死無德色，掉臂不爲曳裾客。
但使鄉鄰少卧痾，眼底名醫麻竹多。
嗟予詩瘦仍多病，兩旬進尺退不寸。
逢君已晚亦未恨，掃除何曾費餘刃。
長句藉手聊爾耳，真成不直一杯水。', '1195', 'e856056b-edb4-414c-b02d-230d0c87f401', '2025-10-22 06:25:07', '杨万里'),
  (55200, '蛟', '梅堯臣', '橋邊三尺劍，江上六鈞弧。
漢武帝何處，周將軍已無。
織綃深有室，泣淚自爲珠。
誰爲九淵害，人猶能爾圖。', '1040', 'd8dd9d73-30a1-4b1d-a18b-9223c74b183a', '2025-10-22 11:18:46', '梅尧臣'),
  (66240, '成都遨樂詩二十一首 八日太慈寺前蠶市', '田況', '蜀雖云樂土，民勤過四方。
寸壤不容隙，僅能充歲糧。
間或容墮孏，曷能備凶痒。
所以農桑具，市易時相望。
野氓集廣鄽，衆賈趨寶坊。
惇本誠急務，戒其靡愆常。
茲會良足喜，後賢勿忽忘。', '1045', 'b4f5c197-6fe3-4b97-8a40-f081b4512978', '2025-10-22 15:49:51', '田况'),
  (77280, '落日窗中坐 領邊繡', '歐陽修', '雙鴛刺繡領，粲爛五文章。
暫近已復遠，猶持歌扇障。', '1045', '40227ad0-60dd-4b6a-9c4e-b0680463482e', '2025-10-22 19:58:56', '欧阳修'),
  (88320, '柳絮二闋  其一', '韓琦', '慣惱東風不定家，高樓長陌奈無涯。
一春情緒空撩亂，不是天生穩重花。', '1044', '612dc71f-54c0-4036-9126-b38df1878ad6', '2025-10-23 00:01:40', '韩琦'),
  (99360, '次韻范師道龍圖三首  其二', '趙抃', '八月湖平絕越通，桐江烟水亂山中。
客舟安穩尤爲幸，百尺蒲帆一信風。', '1056', '302738d6-1275-4248-8f5f-33c43b03d8d1', '2025-10-23 04:52:42', '赵抃'),
  (110400, '九華山', '潘閬', '將齊華嶽猶多六，若並巫山又欠三。
好是雨餘江上望，白雲堆裏潑濃藍。', '985', '2dfbe4ad-d32c-4b1a-a91a-4de97d796086', '2025-10-23 09:36:40', '潘阆'),
  (121440, '次前韻寄鄭悅齋', '王柏', '單騎衝寒發路東，只緣歸計太疎空。
三年事外多閑日，一別花間幾信風。
出處莫期當世合，功名要與古人同。
憑君試問真消息，應已西興喚短篷。', '1240', '1b8d7dc5-fa2f-406a-a541-19bbfcbb7e75', '2025-10-23 13:58:34', '王柏'),
  (132480, '大象吟', '邵雍', '大象自中虛，中虛真不渝。
施爲心事業，應對口功夫。
伎倆千般有，憂愁一點無。
人能知此理，勝讀五車書。', '1070', 'dda8a02d-e681-444c-8254-e0481f69017e', '2025-10-23 18:02:43', '邵雍'),
  (143520, '偈三首  其三', '釋洪英', '石門巇嶮鐵關牢，舉目重重萬仞高。
無角鐵牛衝得破，毗盧海內作波濤。', '1070', '6d155333-a788-4145-ba5b-cc54c550f18e', '2025-10-23 21:53:49', '释洪英'),
  (154560, '和鄭閎中仙居十一首  其五', '陳襄', '我愛仙居好，官卑分已盈。
才非漢循吏，道似魯狂生。
擊柝心雖樂，觀民志未平。
寧如孟夫子，不食去齊卿。', '1065', '976f4e2a-ac60-4f77-8fc1-f3eee69a8dce', '2025-10-24 02:17:01', '陈襄'),
  (165600, '和景純栽松  其一', '韓維', '芳根出澗底，秀木依牆東。
莫顧一時好，當觀三世空。', '1075', '343e0723-2878-4689-a923-1c34c3086c96', '2025-10-24 06:47:19', '韩维'),
  (176640, '次韵劉叔貢舍人從駕', '蘇頌', '鼇頭星掖貴兼清，不似南宮散六卿。
繼踵棣華聯禁直，並時蘭玉占高名。
甘泉法從皆才傑，皇祐孤臣獨老生。
自嘆荆枝半凋落，若論宗戚亦霑榮。', '1068', '45b2bae6-d549-43c8-ab74-74e19ef28cf9', '2025-10-24 11:07:37', '苏颂'),
  (187680, '啄木鳥二首  其二', '魏野', '亂遶園林啄，終朝意若何。
莫因饑不足，翻愛蠹偏多。
渴映鄰溪下，驚從別樹過。
辛懃詠還囑，無損好枝柯。', '1009', '085234d3-d885-48bb-a0e4-33abec50b433', '2025-10-24 17:25:29', '魏野'),
  (198720, '小隠', '林逋', '門徑獨蕭然，山林屋舍邊。
水風清晚釣，花日重春眠。
苒苒苔衣滑，磷磷石子圓。
人寰諸洞府，應合署閒仙。', '1020', 'f3cd1fa8-7675-4055-9216-af7271931a8c', '2025-10-24 21:24:20', '林逋'),
  (209760, '樞密王左丞宅新菊', '楊億', '中樞多暇日，小圃占秋光。
雕玉新成檻，繁金乍泛觴。
陶籬侵柳色，羅宅掩蘭芳。
芝影連虚室，萱叢接後堂。
傅巖猶借雨，豐嶺未飛霜。
温樹徧分蔭，芸籖亦鬬香。
交枝迷露井，墜葉點横塘。
桐錄知延壽，千齡奉紫皇。', '1008', '7e200b7e-4f4d-4dea-aa90-7b1f9393ce65', '2025-10-25 01:40:34', '杨亿'),
  (220800, '送僧歸護國寺', '呂夷簡', '赤城千仞聳霞標，聞說精藍近石橋。
久向天廚分凈供，忽游人落赴嘉招。
逾年華館留禪榻，幾宿輕航兀夜潮。
深愧山陰許都講，肯隨支遁出塵囂。', '1029', '5ac69d20-dabb-4e88-9743-f8a57c7e8224', '2025-10-25 06:10:49', '吕夷简'),
  (231840, '得李四宗易書', '范仲淹', '秋風海上憶神交，江外書來慰寂寥。
松柏舊心當化石，塤篪新韻似聞韶。
須期管鮑垂千古，不學張陳負一朝。
三復荆州無限意，王孫芳草路遙遙。', '1046', '1f381136-e8b6-4d21-b2f7-4dffb8451985', '2025-10-25 10:38:16', '范仲淹'),
  (242880, '崇陽道中作四首  其四', '李綱', '連年兵甲興，猶幸東南稔。
食足無叛民，閭里得安枕。
傳聞江淮間，蝗旱今猶甚。
努力事燮調，未寒心已凛。', '1128', '08988c5e-8237-4589-acc2-c077b6b7ad73', '2025-10-25 15:02:22', '李纲'),
  (253920, '相和歌辭 長歌行', '李白', '桃李得日開，榮華照當年。
東風動百物，草木盡欲言。
枯枝無醜葉，涸水吐清泉。
大力運天地，羲和無停鞭。
功名不早著，竹帛將何宣？
桃李務青春，誰能貫白日。
富貴與神仙，蹉跎成兩失。
金石猶銷鑠，風霜無久質。
畏落日月後，強歡歌與酒。
秋霜不惜人，倏忽侵蒲柳。', '742', '24eec460-2dda-41a7-8104-e590096f3e03', '2025-10-25 19:07:41', '李白'),
  (264960, '雜曲歌辭 楊柳枝 三', '孫魴', '暖傍離亭靜拂橋，入流穿檻綠搖搖。
不知落日誰相送，魂斷千條與萬條。', '935', 'b49c6ed5-cfe9-4e7f-887b-09c32f5ea770', '2025-10-25 22:56:20', '孙鲂'),
  (276000, '芳樹', '宋之問', '何地早芳菲，宛在長門殿。
夭桃色若綬，穠李光如練。
啼鳥弄花疎，遊蜂飲香遍。
歎息春風起，飄零君不見。', '705', '7637858b-ae90-4d68-9696-83eebfd4770f', '2025-10-26 03:03:54', '宋之问'),
  (287040, '望月有所思', '駱賓王', '九秋涼風肅，千里月華開。
圓光隨露湛，碎影逐波來。
似霜明玉砌，如鏡寫珠胎。
晚色依關近，邊聲雜吹哀。
離居分照耀，怨緒共裴徊。
自繞南飛羽，空忝北堂才。', '680', '81202d59-dad1-4a4c-917e-a9ee07931976', '2025-10-26 07:16:07', '骆宾王'),
  (298080, '祭汾陰樂章', '源光裕', '方丘既膳，嘉饗載謐。
齋敬畢誠，陶匏貴質。
秀畢豐薦，芳俎盈實。
永永福流，其升如日。', '730', 'd2ee20f6-53b2-4743-836e-518ab9abe749', '2025-10-26 11:24:09', '源光裕'),
  (309120, '郡齋感秋寄諸弟', '韋應物', '首夏辭舊國，窮秋臥滁城。
方如昨日別，忽覺徂歲驚。
高閣收煙霧，池水晚澄清。
戶牖已淒爽，晨夜感深情。
昔遊郎署間，是月天氣晴。
授衣還西郊，曉露田中行。
采菊投酒中，昆弟自同傾。
簪組聊掛壁，焉知有世榮。
一旦居遠郡，山川間音形。
大道庶無累，及茲念已盈。', '783', 'be54a9d9-f2b3-415a-90ec-0ed7708e64f2', '2025-10-26 15:28:28', '韦应物'),
  (320160, '无题', '沈瀛', '潇洒云中鹤，容与水边鸥。
缑山仙客，飘然曾约此中留。
更有骑鲸公子，相与翱翔八极，凛凛气横秋。
明月楼头宴，樽俎好诗流。
思往事，增逸兴，唤仙舟。
谁能拘束，尘埃堆里蹙昏眸。
拟附星槎直上，十二玉京绛阕，高处且嬉游。
回首视人世，天地一沙舟。
 >> 
词牌介绍', '1180', NULL, '2025-10-26 19:30:16', '沈瀛'),
  (331200, '无题', '许古', '--(1157－1230)字道真，河间(今属河北)　人。明昌五年(1194)进士。后以左司谏致　仕。存词二首。', '1205', NULL, '2025-10-26 23:19:35', '许古');

